/* =====================================================================
   CƠ SỞ DỮ LIỆU QUẢN LÝ CỬA HÀNG SỬA CHỮA XE MÁY
   SQL Server - chạy toàn bộ file bằng F5 trong SSMS
   Dữ liệu demo: 01/08/2026 - 27/10/2026, không có giá trị NULL
   Mật khẩu demo của mọi nhân viên: 123456 (lưu dạng SHA-256 HEX)
   ===================================================================== */

USE master;
GO
IF DB_ID(N'QuanLySuaXe') IS NOT NULL
BEGIN
    ALTER DATABASE QuanLySuaXe SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE QuanLySuaXe;
END
GO
CREATE DATABASE QuanLySuaXe COLLATE Vietnamese_CI_AS;
GO
USE QuanLySuaXe;
GO

/* =====================================================================
   PHẦN 1: TẠO BẢNG
   ===================================================================== */

-- ---------- Nhân sự ----------
CREATE TABLE ChucVu (
    MaChucVu        VARCHAR(10)    NOT NULL,
    TenChucVu       NVARCHAR(100)  NOT NULL,
    MoTa            NVARCHAR(255)  NOT NULL,
    HeSoLuong       DECIMAL(4,2)   NOT NULL,
    TienDieuChinh   DECIMAL(18,0)  NOT NULL,   -- tổng các khoản điều chỉnh của chức vụ
    CONSTRAINT PK_ChucVu PRIMARY KEY (MaChucVu),
    CONSTRAINT UQ_ChucVu_Ten UNIQUE (TenChucVu),
    CONSTRAINT CK_ChucVu_HeSoLuong CHECK (HeSoLuong > 0)
);

CREATE TABLE KhoanDieuChinh (
    MaKhoanDieuChinh   VARCHAR(10)    NOT NULL,
    TenKhoanDieuChinh  NVARCHAR(150)  NOT NULL,
    SoTien             DECIMAL(18,0)  NOT NULL,   -- dương: phụ cấp/thưởng, âm: phạt
    CONSTRAINT PK_KhoanDieuChinh PRIMARY KEY (MaKhoanDieuChinh),
    CONSTRAINT CK_KhoanDieuChinh_SoTien CHECK (SoTien <> 0)
);

CREATE TABLE ChucVuDieuChinh (
    MaChucVu          VARCHAR(10) NOT NULL,
    MaKhoanDieuChinh  VARCHAR(10) NOT NULL,
    CONSTRAINT PK_ChucVuDieuChinh PRIMARY KEY (MaChucVu, MaKhoanDieuChinh),
    CONSTRAINT FK_CVDC_ChucVu FOREIGN KEY (MaChucVu) REFERENCES ChucVu(MaChucVu),
    CONSTRAINT FK_CVDC_KhoanDieuChinh FOREIGN KEY (MaKhoanDieuChinh) REFERENCES KhoanDieuChinh(MaKhoanDieuChinh)
);

CREATE TABLE NhanVien (
    MaNhanVien   VARCHAR(10)    NOT NULL,
    MaChucVu     VARCHAR(10)    NOT NULL,
    HoTen        NVARCHAR(100)  NOT NULL,
    SoDienThoai  VARCHAR(15)    NOT NULL,
    Luong        DECIMAL(18,0)  NOT NULL,
    TenDangNhap  VARCHAR(50)    NOT NULL,
    MatKhau      VARCHAR(64)    NOT NULL,   -- SHA-256 dạng HEX
    TrangThai    NVARCHAR(20)   NOT NULL,
    CONSTRAINT PK_NhanVien PRIMARY KEY (MaNhanVien),
    CONSTRAINT FK_NhanVien_ChucVu FOREIGN KEY (MaChucVu) REFERENCES ChucVu(MaChucVu),
    CONSTRAINT UQ_NhanVien_SoDienThoai UNIQUE (SoDienThoai),
    CONSTRAINT UQ_NhanVien_TenDangNhap UNIQUE (TenDangNhap),
    CONSTRAINT CK_NhanVien_Luong CHECK (Luong > 0),
    CONSTRAINT CK_NhanVien_TrangThai CHECK (TrangThai IN (N'Đang làm', N'Nghỉ việc'))
);

CREATE TABLE CaLam (
    MaCaLam          VARCHAR(10)   NOT NULL,
    ThoiGianCaLam    DECIMAL(4,2)  NOT NULL,   -- số giờ của ca
    ThoiGianBatDau   TIME(0)       NOT NULL,
    ThoiGianKetThuc  TIME(0)       NOT NULL,
    CONSTRAINT PK_CaLam PRIMARY KEY (MaCaLam),
    CONSTRAINT CK_CaLam_ThoiGian CHECK (ThoiGianKetThuc > ThoiGianBatDau AND ThoiGianCaLam > 0)
);

CREATE TABLE ChiTietCaLam (
    MaNhanVien             VARCHAR(10)   NOT NULL,
    MaCaLam                VARCHAR(10)   NOT NULL,
    NgayLam                DATE          NOT NULL,
    TongThoiGianLamThucTe  DECIMAL(4,2)  NOT NULL,   -- số giờ thực tế
    CONSTRAINT PK_ChiTietCaLam PRIMARY KEY (MaNhanVien, MaCaLam, NgayLam),
    CONSTRAINT FK_CTCL_NhanVien FOREIGN KEY (MaNhanVien) REFERENCES NhanVien(MaNhanVien),
    CONSTRAINT FK_CTCL_CaLam FOREIGN KEY (MaCaLam) REFERENCES CaLam(MaCaLam),
    CONSTRAINT CK_CTCL_TongThoiGian CHECK (TongThoiGianLamThucTe >= 0)
);

-- ---------- Khách hàng - Xe ----------
CREATE TABLE KhachHang (
    MaKhachHang   VARCHAR(10)    NOT NULL,
    TenKhachHang  NVARCHAR(100)  NOT NULL,
    SoDienThoai   VARCHAR(15)    NOT NULL,
    CONSTRAINT PK_KhachHang PRIMARY KEY (MaKhachHang),
    CONSTRAINT UQ_KhachHang_SoDienThoai UNIQUE (SoDienThoai)
);

CREATE TABLE Xe (   -- mỗi lượt xe vào cửa hàng là một bản ghi Xe mới
    MaXe         VARCHAR(10)    NOT NULL,
    MaKhachHang  VARCHAR(10)    NOT NULL,
    BienXe       VARCHAR(20)    NOT NULL,
    LoaiXe       NVARCHAR(50)   NOT NULL,
    HangSanXuat  NVARCHAR(50)   NOT NULL,
    MauSac       NVARCHAR(30)   NOT NULL,
    CONSTRAINT PK_Xe PRIMARY KEY (MaXe),
    CONSTRAINT FK_Xe_KhachHang FOREIGN KEY (MaKhachHang) REFERENCES KhachHang(MaKhachHang)
);

CREATE TABLE ChiTietPhanCong (
    MaNhanVien         VARCHAR(10)   NOT NULL,
    MaXe               VARCHAR(10)   NOT NULL,
    ThoiGianBatDau     DATETIME2(0)  NOT NULL,
    ThoiGianHoanThanh  DATETIME2(0)  NOT NULL,
    CONSTRAINT PK_ChiTietPhanCong PRIMARY KEY (MaNhanVien, MaXe),
    CONSTRAINT FK_CTPC_NhanVien FOREIGN KEY (MaNhanVien) REFERENCES NhanVien(MaNhanVien),
    CONSTRAINT FK_CTPC_Xe FOREIGN KEY (MaXe) REFERENCES Xe(MaXe),
    CONSTRAINT CK_CTPC_ThoiGian CHECK (ThoiGianHoanThanh > ThoiGianBatDau)
);

-- ---------- Dịch vụ - Phụ tùng - Nhập kho ----------
CREATE TABLE DichVu (
    MaDichVu         VARCHAR(10)    NOT NULL,
    TenDichVu        NVARCHAR(150)  NOT NULL,
    MoTa             NVARCHAR(255)  NOT NULL,
    ThanhTienDichVu  DECIMAL(18,0)  NOT NULL,
    TrangThai        NVARCHAR(20)   NOT NULL,
    CONSTRAINT PK_DichVu PRIMARY KEY (MaDichVu),
    CONSTRAINT CK_DichVu_Gia CHECK (ThanhTienDichVu > 0),
    CONSTRAINT CK_DichVu_TrangThai CHECK (TrangThai IN (N'Đang áp dụng', N'Ngừng áp dụng'))
);

CREATE TABLE NhaCungCap (
    MaNhaCungCap   VARCHAR(10)    NOT NULL,
    TenNhaCungCap  NVARCHAR(150)  NOT NULL,
    SoDienThoai    VARCHAR(15)    NOT NULL,
    DiaChi         NVARCHAR(255)  NOT NULL,
    CONSTRAINT PK_NhaCungCap PRIMARY KEY (MaNhaCungCap)
);

CREATE TABLE PhuTung (   -- khác NCC hoặc khác hạn sử dụng => mã phụ tùng mới
    MaPhuTung     VARCHAR(10)    NOT NULL,
    MaNhaCungCap  VARCHAR(10)    NOT NULL,
    TenPhuTung    NVARCHAR(150)  NOT NULL,
    DonGiaNhap    DECIMAL(18,0)  NOT NULL,
    DonGiaBan     DECIMAL(18,0)  NOT NULL,
    SoLuongTon    INT            NOT NULL,
    HanSuDung     DATE           NOT NULL,
    TrangThai     NVARCHAR(20)   NOT NULL,
    CONSTRAINT PK_PhuTung PRIMARY KEY (MaPhuTung),
    CONSTRAINT FK_PhuTung_NhaCungCap FOREIGN KEY (MaNhaCungCap) REFERENCES NhaCungCap(MaNhaCungCap),
    CONSTRAINT CK_PhuTung_Gia CHECK (DonGiaNhap > 0 AND DonGiaBan >= DonGiaNhap),
    CONSTRAINT CK_PhuTung_SoLuongTon CHECK (SoLuongTon >= 0),
    CONSTRAINT CK_PhuTung_TrangThai CHECK (TrangThai IN (N'Đang kinh doanh', N'Ngừng kinh doanh'))
);

CREATE TABLE ChiTietDichVu (   -- định mức phụ tùng cho mỗi dịch vụ
    MaDichVu   VARCHAR(10) NOT NULL,
    MaPhuTung  VARCHAR(10) NOT NULL,
    SoLuong    INT         NOT NULL,
    CONSTRAINT PK_ChiTietDichVu PRIMARY KEY (MaDichVu, MaPhuTung),
    CONSTRAINT FK_CTDV_DichVu FOREIGN KEY (MaDichVu) REFERENCES DichVu(MaDichVu),
    CONSTRAINT FK_CTDV_PhuTung FOREIGN KEY (MaPhuTung) REFERENCES PhuTung(MaPhuTung),
    CONSTRAINT CK_CTDV_SoLuong CHECK (SoLuong > 0)
);

CREATE TABLE PhieuNhap (
    MaPhieuNhap     VARCHAR(10)    NOT NULL,
    MaNhanVienNhap  VARCHAR(10)    NOT NULL,
    NgayNhap        DATE           NOT NULL,
    GhiChu          NVARCHAR(255)  NOT NULL,
    TongTienNhap    DECIMAL(18,0)  NOT NULL,
    CONSTRAINT PK_PhieuNhap PRIMARY KEY (MaPhieuNhap),
    CONSTRAINT FK_PhieuNhap_NhanVien FOREIGN KEY (MaNhanVienNhap) REFERENCES NhanVien(MaNhanVien),
    CONSTRAINT CK_PhieuNhap_TongTien CHECK (TongTienNhap >= 0)
);

CREATE TABLE ChiTietPhieuNhap (
    MaPhieuNhap  VARCHAR(10)    NOT NULL,
    MaPhuTung    VARCHAR(10)    NOT NULL,
    SoLuongNhap  INT            NOT NULL,
    ThanhTien    DECIMAL(18,0)  NOT NULL,
    CONSTRAINT PK_ChiTietPhieuNhap PRIMARY KEY (MaPhieuNhap, MaPhuTung),
    CONSTRAINT FK_CTPN_PhieuNhap FOREIGN KEY (MaPhieuNhap) REFERENCES PhieuNhap(MaPhieuNhap),
    CONSTRAINT FK_CTPN_PhuTung FOREIGN KEY (MaPhuTung) REFERENCES PhuTung(MaPhuTung),
    CONSTRAINT CK_CTPN_SoLuong CHECK (SoLuongNhap > 0 AND ThanhTien >= 0)
);

-- ---------- Tiếp nhận - Hóa đơn ----------
CREATE TABLE PhieuTiepNhan (
    MaPhieuTiepNhan  VARCHAR(10)   NOT NULL,
    MaXe             VARCHAR(10)   NOT NULL,
    MaNhanVien       VARCHAR(10)   NOT NULL,   -- "Mã NV" trên sơ đồ: nhân viên lập phiếu
    NgayLap          DATE          NOT NULL,
    NgayHen          DATE          NOT NULL,
    TrangThai        NVARCHAR(20)  NOT NULL,
    CONSTRAINT PK_PhieuTiepNhan PRIMARY KEY (MaPhieuTiepNhan),
    CONSTRAINT FK_PTN_Xe FOREIGN KEY (MaXe) REFERENCES Xe(MaXe),
    CONSTRAINT FK_PTN_NhanVien FOREIGN KEY (MaNhanVien) REFERENCES NhanVien(MaNhanVien),
    CONSTRAINT CK_PTN_NgayHen CHECK (NgayHen >= NgayLap),
    CONSTRAINT CK_PTN_TrangThai CHECK (TrangThai IN (N'Chờ sửa', N'Đang sửa', N'Hoàn thành', N'Đã hủy'))
);

CREATE TABLE ChiTietPhieuTiepNhan (
    MaPhieuTiepNhan  VARCHAR(10)    NOT NULL,
    MaDichVu         VARCHAR(10)    NOT NULL,
    SoLuong          INT            NOT NULL,
    ThanhTien        DECIMAL(18,0)  NOT NULL,
    CONSTRAINT PK_ChiTietPhieuTiepNhan PRIMARY KEY (MaPhieuTiepNhan, MaDichVu),
    CONSTRAINT FK_CTPTN_PhieuTiepNhan FOREIGN KEY (MaPhieuTiepNhan) REFERENCES PhieuTiepNhan(MaPhieuTiepNhan),
    CONSTRAINT FK_CTPTN_DichVu FOREIGN KEY (MaDichVu) REFERENCES DichVu(MaDichVu),
    CONSTRAINT CK_CTPTN_SoLuong CHECK (SoLuong > 0 AND ThanhTien >= 0)
);

CREATE TABLE HoaDon (
    MaHoaDon         VARCHAR(10)    NOT NULL,
    MaPhieuTiepNhan  VARCHAR(10)    NOT NULL,
    TienThanhToan    DECIMAL(18,0)  NOT NULL,
    NgayLap          DATE           NOT NULL,
    NgayThanhToan    DATE           NOT NULL,
    CONSTRAINT PK_HoaDon PRIMARY KEY (MaHoaDon),
    CONSTRAINT FK_HoaDon_PhieuTiepNhan FOREIGN KEY (MaPhieuTiepNhan) REFERENCES PhieuTiepNhan(MaPhieuTiepNhan),
    CONSTRAINT UQ_HoaDon_PhieuTiepNhan UNIQUE (MaPhieuTiepNhan),   -- 1 phiếu : 1 hóa đơn
    CONSTRAINT CK_HoaDon_Ngay CHECK (NgayThanhToan >= NgayLap),
    CONSTRAINT CK_HoaDon_Tien CHECK (TienThanhToan >= 0)
);
GO

